import { useEffect, useState } from 'react';

/**
 * Weekly scores, generated by scripts/schedule_content.py from data/y80/schedules.json (schedule.set):
 * public/data/league/schedule.json. Rules only; the site never edits it.
 */
export const SCHEDULE_URL = `${import.meta.env.BASE_URL}data/league/schedule.json`;

export interface CoachGame {
  week: number;
  /** "Week 3", "Bye", "Divisional", "Conference", "Super Bowl" … */
  round: string;
  site?: 'home' | 'away';
  /** Opponent nickname ("Commanders") and abbreviation ("WAS") */
  opp?: string;
  oppAbbr?: string;
  for?: number;
  against?: number;
  result?: 'W' | 'L' | 'T';
  margin?: number;
  /** Winner's score first ("48-23") */
  score?: string;
  /** Opponent's final record ("11-5-1") and the season summary screen's offense / defense ratings (0–5 stars) */
  oppRecord?: string;
  oppOff?: number;
  oppDef?: number;
  playoff?: boolean;
}

export interface TableRow {
  team: string;
  abbr: string;
  conference?: string | null;
  division?: string | null;
  divisionRank?: number | null;
  w: number;
  l: number;
  t: number;
  record: string;
  pct: number;
  pf: number;
  pa: number;
  diff: number;
  ppg: number;
  papg: number;
  /** Strength of schedule: average final win % of the clubs it played */
  sos: number;
  /** 100 × win % + 1.5 × diff per game + 40 × (SOS − 0.5) */
  powerScore: number;
  power: number;
  /** Regular-season splits: home, away and one-score (decided by 8 or fewer, ties included) records ("7-2") */
  home?: string;
  away?: string;
  oneScore?: string;
  longestWinStreak?: number;
  /** Current streak at season's end ("W7") and the last five results, oldest first ("WWLWW") */
  streak?: string;
  last5?: string;
  /** Every regular-season result in game order ("WLWWT…") */
  results?: string;
  /** Pythagorean win expectation (exponent 2.37), its expected wins, and luck (actual wins minus expected) */
  pythag?: number;
  expWins?: number;
  luck?: number;
  /** Consistency: standard deviation of game margins (lower is steadier) */
  marginSd?: number;
  /** Home win % minus away win % */
  homeEdge?: number;
  /** Margin per game adjusted for the schedule */
  adjMargin?: number;
}

/** One club's season in `progression`, with the change against its previous season that has weekly scores. */
export interface TeamSeasonRow
  extends Partial<Omit<TableRow, 'team' | 'abbr' | 'conference' | 'division' | 'results' | 'longestWinStreak'>> {
  season: string;
  record: string;
  w: number;
  l: number;
  t: number;
  diff: number;
  power: number;
  change?: { power: number; diff: number; wins: number; since: string };
}

export interface GameRef {
  week: number;
  away: string;
  home: string;
  awayScore: number;
  homeScore: number;
  winner: string | null;
  loser: string | null;
  score: string;
  margin: number;
  total: number;
  winnerRecord?: string;
  loserRecord?: string;
}

/** The league's regular season by the numbers. */
export interface LeagueNumbers {
  games: number;
  points: number;
  /** Points per team per game */
  ppg: number;
  /** Average combined points per game */
  combinedAvg: number;
  homeWinPct: number;
  homeWins: number;
  awayWins: number;
  ties: GameRef[];
  /** Games decided by 8 points or fewer (ties excluded) and their share of all games */
  oneScoreGames: number;
  oneScoreShare: number;
  /** Games where a club scored 50 or more */
  fiftyPointGames: number;
  avgMargin: number;
  /** Per week: the league average points per team and the week's high score */
  weeks: { week: number; avg: number; high: number }[];
  closest?: GameRef;
  mostInLoss?: GameRef;
  fewestInWin?: GameRef;
}

export interface CoachGameBrief {
  week: number;
  round: string;
  opp: string;
  for: number;
  against: number;
  margin: number;
}

/** The coached club's season in detail (playoffs included unless noted). */
export interface CoachDetail {
  /** Regular-season home / away records */
  home: string;
  away: string;
  /** Games decided by 8 or fewer */
  oneScore: string;
  /** Regular season against clubs that finished above .500 */
  vsWinning: string;
  vsWinningGames: number;
  ppg: number;
  papg: number;
  /** Average opponent offense / defense rating (0–5 stars) */
  avgOppOff?: number | null;
  avgOppDef?: number | null;
  longestWinStreak?: number | null;
  bestWin?: CoachGameBrief;
  worstLoss?: CoachGameBrief;
  /** W / L / T in game order, playoffs included, byes skipped */
  results: string;
}

export interface ScheduleSeason {
  season: string;
  coachTeam: string;
  coachAbbr: string;
  coachRecord: { w: number; l: number; t: number; pf: number; pa: number; diff: number; power: number; record: string; playoffs: string };
  coachGames: CoachGame[];
  coachDetail?: CoachDetail;
  league?: LeagueNumbers;
  table: TableRow[];
  leaders: { bestOffense: string; bestDefense: string; worstDefense: string; bestDiff: string };
  upset?: GameRef;
  blowout?: GameRef;
  shootout?: GameRef;
  games: { week: number; away: string; home: string; awayScore: number; homeScore: number }[];
  regularSeasonGames: number;
}

export interface HeadToHead {
  team: string;
  w: number;
  l: number;
  t: number;
  record: string;
  games: number;
  meetings: { season: string; week: number; round: string; site: string; coachTeam: string; for: number; against: number; result: 'W' | 'L' | 'T' }[];
}

export interface GameRecord {
  id: string;
  label: string;
  value: number;
  season?: string;
  week?: number;
  away?: string;
  home?: string;
  awayScore?: number;
  homeScore?: number;
  team?: string;
}

export interface Schedule {
  seasons: Record<string, ScheduleSeason>;
  headToHead: Record<string, HeadToHead>;
  records: GameRecord[];
  /** Every club's row for each season with weekly scores, oldest first (missing seasons are simply absent) */
  progression?: Record<string, TeamSeasonRow[]>;
}

const EMPTY: Schedule = { seasons: {}, headToHead: {}, records: [] };

let request: Promise<Schedule> | null = null;
/** Fetches schedule.json once per page load (revalidated, like every data file). A missing file is an empty schedule. */
export const loadSchedule = (): Promise<Schedule> => {
  request ??= fetch(SCHEDULE_URL, { cache: 'no-cache' })
    .then((res) => (res.ok ? res.json() : EMPTY))
    .then((json: Partial<Schedule>) => ({ ...EMPTY, ...json }))
    .catch(() => EMPTY);
  return request;
};

/** Seasons with weekly scores, newest first. */
export const scheduleSeasons = (s: Schedule): ScheduleSeason[] =>
  Object.values(s.seasons).sort((a, b) => Number(b.season.slice(1)) - Number(a.season.slice(1)));

/** The newest season with weekly scores, or null when there are none. */
export const latestScheduleSeason = (s: Schedule): ScheduleSeason | null => scheduleSeasons(s)[0] ?? null;

/** A club's season in one line: record and point differential ("15-2, +119"). */
export const formLine = (row: Pick<TableRow, 'record' | 'diff'>) => `${row.record}, ${row.diff > 0 ? '+' : ''}${row.diff}`;

export const useSchedule = () => {
  const [schedule, setSchedule] = useState<Schedule | null>(null);
  useEffect(() => {
    let cancelled = false;
    loadSchedule().then((s) => {
      if (!cancelled) setSchedule(s);
    });
    return () => {
      cancelled = true;
    };
  }, []);
  return schedule;
};
